import type { Manifest } from "../config/index.ts";

/**
 * Generated Playwright configs. Attach mode (QD11): no webServer, baseURL from the env
 * contract so the same specs replay in the QA CI job and locally.
 */
export function playwrightConfig(manifest: Manifest, options: { testDir: string; outputDir: string }): string {
  const q = JSON.stringify;
  return [
    "// Generated by magpi-test. Regenerated on every run; do not edit.",
    `import { defineConfig } from "@playwright/test";`,
    "",
    "export default defineConfig({",
    `  testDir: ${q(options.testDir)},`,
    `  outputDir: ${q(options.outputDir)},`,
    "  retries: 0,",
    "  workers: 1,",
    "  timeout: 60_000,",
    "  expect: { timeout: 10_000 },",
    "  use: {",
    `    baseURL: process.env.MAGPI_TEST_BASE_URL ?? ${q(manifest.baseURL)},`,
    `    locale: ${q(manifest.locale)},`,
    "    actionTimeout: 10_000,",
    `    trace: "retain-on-failure",`,
    "  },",
    "});",
    "",
  ].join("\n");
}
